head.script:
scwin.test_expression = function(value) {
    return value + "_test";
};
scwin.gridView1_ongroupby = function(options) {
    var flag = true;
    if (flag) {
        options.closeGroup = false;
        options.groupbyHeader = [{
            colSpan: "10",
            inputType: "expression",
            expression: " toggle() + depthStr() + ' [ '+ SUM('col3') +',' + count() + ' 건 ] ' ",
            align: "left"
        }];
        options.groupbyFooter = [{
                colSpan: "7"
            },
            {
                colSpan: "3",
                inputType: "expression",
                expression: " SUM('col3')",
                displayFormatter: "countFormatFunction",
                align: "center"
            }
        ];
        gridView1.groupby(options); //실제 groupby 실행
    } else {
        return false;
    }
};
scwin.countFormatFunction = function(value) {
    return "총판매수량 : " + value + " 개 ";
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setVal = function() {
    scwin.simulateWrapper('#gridView1_column19', 'drag-n-drop', {
        dx: 0,
        dy: -60
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_1_1 input:checked').length == 1;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_4_1 input:checked').length == 1;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_7_1 input:checked').length == 1;
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_10_1 input:checked').length == 1;
}
scwin.checkVal5 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_1_1 input:checked').length == 0;
}
scwin.checkVal6 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_4_1 input:checked').length == 0;
}
scwin.checkVal7 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_7_1 input:checked').length == 0;
}
scwin.checkVal8 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_10_1 input:checked').length == 0;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 브라우저에서 임의의 컬럼(name3)을 Groupb By Zone 에 드래그 & 드랍한다. (예 : name3)
    //1. Drag and drop any column (name3) from the browser to the Groupb By Zone. (For example, name3)
    //Verify step 1. The name3 column is grouped.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == 'name3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 헤더의 전체선택박스를 체크한다.
    //2. Check the Full Selection box in the header.
    //Verify step 2. The entire item is selected (previously the second row item is not selected).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#gridView1_column1944 input').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 헤더의 전체해제를 선택한다.
    //3. Select Release entire header.
    //Verify step 3. The entire item is released.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#gridView1_column1944 input').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal7()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal8()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "col1": "a1",
        "col3": "10"
    }, {
        "col1": "a2",
        "col3": "20"
    }, {
        "col1": "a3",
        "col3": "30"
    }, {
        "col1": "a4",
        "col3": "40"
    }];
    dataList1.setJSON(jsonData);
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 27-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
